var PROGRAM_KEY_RE = /^[0-9a-f]{64}$/;
async function programKey(x) {
  const p = checkShared(x), ast = parse(p.src);
  validate(ast);
  const bytes = new TextEncoder().encode(`${p.grid}|${p.lattice}|${p.tone}|${serialize(ast)}`);
  const d = new Uint8Array(await crypto.subtle.digest("SHA-256", bytes));
  return [...d].map((b) => b.toString(16).padStart(2, "0")).join("");
}
var WIDGET_UIDS = new Set(catalog.map((r) => r[1]).filter(Boolean));
export {
  PROGRAM_KEY_RE,
  WIDGET_UIDS,
  programKey
};
